mapper.select:
SELECT COALESCE(SUM(u.sessions), 0)    AS sessions,
       COALESCE(SUM(u.messages), 0)    AS messages,
       COALESCE(SUM(u.ai_calls), 0)    AS ai_calls,
       COALESCE(MAX(u.seats), 0)       AS seats,
       COALESCE(MAX(u.storage_gb), 0)  AS storage_gb,
       COUNT(1)                        AS days
  FROM billing_usage_daily u
 WHERE u.tenant_code = #{tenantCode}
   AND u.stat_date >= #{from}
   AND u.stat_date <= #{to}

SELECT u.stat_date AS stat_date, u.sessions, u.messages, u.ai_calls, u.seats, u.storage_gb
  FROM billing_usage_daily u
 WHERE u.tenant_code = #{tenantCode}
   AND u.stat_date >= #{from}
   AND u.stat_date <= #{to}
 ORDER BY u.stat_date

SELECT * FROM billing_statement s
 WHERE s.is_deleted = FALSE

   AND s.tenant_code = #{tenantCode}


   AND s.cycle_key = #{cycleKey}


   AND s.status = #{status}

 ORDER BY s.cycle_key DESC, s.id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM billing_statement s
 WHERE s.is_deleted = FALSE

   AND s.tenant_code = #{tenantCode}


   AND s.cycle_key = #{cycleKey}


   AND s.status = #{status}

mapper.sql:
o.is_deleted = FALSE

    AND o.tenant_code = #{tenantCode}


    AND o.status = #{status}


    AND o.plan_id = #{planId}


    AND o.cycle = #{payCycle}


    AND o.pay_method = #{payMethod}


    AND to_char(o.pay_time, 'YYYY-MM') = #{cycleKey}


    AND o.pay_time >= #{payFrom}::timestamp


    AND o.pay_time < (#{payTo}::timestamp + INTERVAL '1 day')


    AND (o.order_no ILIKE '%' || #{keyword} || '%'
         OR o.tenant_code ILIKE '%' || #{keyword} || '%')
